  void Versioned(Guid id,Dictionary<string,CardDataRights> map){if(id==Guid.Empty)return;var root=new Dictionary<string,CardDataRights>(map);foreach(string sid in root.Keys.ToArray())if(root[sid]!=Full)root[sid]&=~CardDataRights.DeleteChildObjects;Card(id,root);var vf=(VersionedFileCard)Runtime.S.CardManager.GetCard(id);foreach(var version in vf.Versions)FileRights(version,map);}
  public void Apply(){Directory.CreateDirectory(dir);var c=Runtime.C;var s=Runtime.S;var staff=c.GetObject<Staff>(G("6710b92a-e148-4363-8a6f-1aa0eb18936c"));Index(staff.Units);var groupRoot=staff.Groups.Single(g=>g.Name=="АГОРА — Исходящие письма");foreach(var group in groupRoot.Groups)groups[group.GetObjectId()]=group;var definitions=NewRights();
   foreach(var e in employees.Values){var visited=new HashSet<Guid>();for(var unit=e.Unit;unit!=null&&visited.Add(unit.GetObjectId());unit=unit.ParentUnit)if(new[]{G("4900f7b1-472c-447d-bc0a-7d460937ceb8"),G("691c36db-f7da-4497-9f9b-6930083bf85c"),G("617ac655-38d4-4dab-9654-7865dc630b10")}.Contains(unit.GetObjectId())){Add(definitions,e,Read|CardDataRights.PerformOperations);break;}}
   var config=Runtime.Read<Dictionary<string,object>>(Path.Combine(Runtime.Root,"approval-config.json"));foreach(string key in new[]{"paths","stages"})foreach(var entry in (Dictionary<string,object>)config[key])Card(G((string)entry.Value),definitions);
   foreach(string name in new[]{"assignment-config.xml","registration-config.xml"}){var xml=new XmlDocument{XmlResolver=null};xml.Load(Path.Combine(Runtime.Root,@"server\"+name));foreach(XmlElement node in xml.SelectNodes("//Counter")){Guid id=G(node.GetAttribute("id"));var counter=(NumeratorCard)s.CardManager.GetCard(id);int year=TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Russian Standard Time")).Year;foreach(int y in new[]{year,year+1})if(!counter.Zones.Any(z=>z.Name=="Y"+y))counter.Zones.AddNew("Y"+y);Card(id,definitions);}}
   var taskService=c.GetService<ITaskService>();var stageService=c.GetService<IApprovalTaskService>();var failures=new List<object>();
   foreach(CardData raw in s.CardManager.FindCards(Runtime.Query(null).GetXml()))try{var sys=raw.Sections[Runtime.Sys].FirstRow;var main=raw.Sections[Runtime.Main].FirstRow;var extra=raw.Sections[Runtime.Extra].FirstRow;Guid state=Runtime.Id(sys,"State");bool draft=state==G("ab48f98d-3637-48aa-92bd-556bc88475c6");var map=NewRights();var author=Employee(Runtime.Id(main,"Author"));CardDataRights authorRights=draft||state==G("bcc23707-c0aa-4b2c-bbec-3b6ff751aca5")||state==G("11b0eb5d-3fa1-48a9-ba0b-e9ed1c2b1510")?Modify:Read;var doc=c.GetObject<Document>(raw.Id);if(draft&&(doc.MainInfo.SignatureList==null||doc.MainInfo.SignatureList.Signatures.Count==0))authorRights|=CardDataRights.Delete;Add(map,author,authorRights);Group(map,G("942df52e-50b6-4d67-b537-b82c46ade308"),Full);Guid journalGroup;bool hasGroup=JournalGroups.TryGetValue(Runtime.Id(extra,"Journal"),out journalGroup);
    if(draft){Group(map,G("4adf3c4e-aae8-466e-be68-91eba2c2dc89"),Modify);if(hasGroup)Group(map,journalGroup,Modify);}else{Manager(map,author);Add(map,Employee(Runtime.Id(extra,"InitiatorManager")),Read);foreach(var person in new[]{new[]{"d9f3bb4c-9c1a-464c-90f3-3d9657864709","Signer"},new[]{"281a97ff-667f-46c8-8fbe-7cfc02edfedb","Approver"}})foreach(RowData row in raw.Sections[G(person[0])].Rows){var e=Employee(Runtime.Id(row,person[1]));Manager(map,e);Add(map,e,Read);}if(hasGroup)Group(map,journalGroup,state==G("11b0eb5d-3fa1-48a9-ba0b-e9ed1c2b1510")?Modify:Read);Group(map,G("483fe3ce-a4d9-41c9-a00d-e559ceaee982"),Read);Group(map,G("fa66bc1f-0da1-4391-8209-80b19d0c6040"),Read);}
    Reconcile reconcile=null;var writers=new List<StaffEmployee>();var tasks=new List<DocsVision.BackOffice.ObjectModel.Task>();Guid history=Runtime.Id(extra,"ActiveApprovalId");if(history!=Guid.Empty){reconcile=c.GetObject<Reconcile>(history);if(reconcile.MainInfo.Document==null||reconcile.MainInfo.Document.GetObjectId()!=raw.Id)throw new InvalidOperationException("Approval belongs to different document");foreach(var entry in reconcile.MainInfo.TaskList.Tasks){var task=entry.Task;if(task==null)continue;tasks.Add(task);Add(map,task.MainInfo.CompletedUser,Read);foreach(var p in task.CurrentPerformers){Add(map,p.Employee,Read);if(!taskService.IsTaskCompleted(task)){var stage=stageService.GetTaskApprovalStage(task);if(stage.MainInfo.Mode==ApprovalStageMode.Signing||stage.MainInfo.Mode==ApprovalStageMode.Consolidation||stage.MainInfo.ReconcileType==ApprovalType.Alternative){writers.Add(p.Employee);if(stage.MainInfo.ReconcileType==ApprovalType.Alternative)Add(map,p.Employee,Modify);}}}}}
    var auxQuery=s.CreateSearchQuery();var auxSection=auxQuery.AttributiveSearch.CardTypeQueries.AddNew(G("c7b36f33-cdd4-4da9-8444-600fe14111e4")).SectionQueries.AddNew(G("20d21193-9f7f-4b62-8d69-272e78e1d6a8"));auxSection.ConditionGroup.Conditions.AddNew("ParentDocument",FieldType.RefId,ConditionOperation.Equals,raw.Id);var trusted=new List<DocsVision.BackOffice.ObjectModel.Task>();foreach(CardData auxRaw in s.CardManager.FindCards(auxQuery.GetXml()))if(!tasks.Any(t=>t.GetObjectId()==auxRaw.Id)){string record=Path.Combine(Runtime.StateRoot,@"trusted-auxiliary\"+auxRaw.Id.ToString("N")+".xml");if(!File.Exists(record))continue;var proof=new XmlDocument{XmlResolver=null};proof.Load(record);var root=proof.DocumentElement;if(root.Name!="TrustedAuxiliaryTask"||G(root.GetAttribute("document"))!=raw.Id||G(root.GetAttribute("task"))!=auxRaw.Id)continue;var aux=c.GetObject<DocsVision.BackOffice.ObjectModel.Task>(auxRaw.Id);if(aux.MainInfo.Author==null||aux.MainInfo.Author.GetObjectId()!=G(root.GetAttribute("author"))||aux.SystemInfo.CardKind.GetObjectId()!=G(root.GetAttribute("kind")))continue;tasks.Add(aux);trusted.Add(aux);}
    string participants=Path.Combine(dir,"participants-"+raw.Id.ToString("N")+".json");var people=new HashSet<Guid>();if(File.Exists(participants)){var stored=Runtime.Read<ParticipantRecord>(participants);if(stored.employees!=null)foreach(string id in stored.employees)people.Add(G(id));}foreach(var task in tasks){if(task.MainInfo.CompletedUser!=null)people.Add(task.MainInfo.CompletedUser.GetObjectId());foreach(var p in task.CurrentPerformers)if(p.Employee!=null)people.Add(p.Employee.GetObjectId());}foreach(Guid id in people)Add(map,Employee(id),Read);Runtime.Save(participants,new ParticipantRecord{employees=people.Select(x=>x.ToString()).OrderBy(x=>x).ToArray()});
    if(raw.LockStatus==LockStatus.Free){var index=raw.Sections[G("4c497917-8a21-4c33-a27a-b95113b530b0")];var old=index.Rows.Cast<RowData>().Select(r=>Runtime.Id(r,"Employee")).OrderBy(x=>x);if(!old.SequenceEqual(people.OrderBy(x=>x))){raw.PlaceLock();try{raw.BeginUpdate();try{foreach(var row in index.Rows.Cast<RowData>().ToArray())index.Rows.Remove(row.Id);foreach(Guid id in people)index.Rows.AddNew().SetGuid("Employee",id);raw.EndUpdate();}catch{raw.CancelUpdate();throw;}}finally{raw.RemoveLock();}}}
    Card(raw.Id,map);if(trusted.Count>0&&raw.LockStatus==LockStatus.Free){var lists=c.GetService<ITaskListService>();var list=doc.MainInfo.Tasks;if(list==null){list=lists.CreateTaskList();c.SaveObject(list);doc.MainInfo.Tasks=list;c.SaveObject(doc);}foreach(var aux in trusted)if(!list.Tasks.Any(t=>t.Task!=null&&t.Task.GetObjectId()==aux.GetObjectId()))lists.AddTask(list,aux,doc);c.SaveObject(list);c.AcceptChanges();Card(list.GetObjectId(),map);}
    foreach(var file in doc.Files)if(file.FileType==DocumentFileType.Main)Versioned(file.FileId,map);else FileRights(s.FileManager.GetFile(file.FileId),map);if(doc.MainInfo.ReferenceList!=null)Card(doc.MainInfo.ReferenceList.GetObjectId(),map);if(doc.MainInfo.SignatureList!=null){Card(doc.MainInfo.SignatureList.GetObjectId(),map);foreach(var signature in doc.MainInfo.SignatureList.Signatures)foreach(var part in signature.Parts)if(part.Signature!=Guid.Empty)FileRights(s.FileManager.GetFile(part.Signature),map);}
    if(reconcile!=null){var graph=new Dictionary<string,CardDataRights>(map);foreach(string sid in graph.Keys.ToArray())if(graph[sid]!=Full)graph[sid]=Read;foreach(var writer in writers)Add(graph,writer,Modify);Card(reconcile.GetObjectId(),graph);Card(reconcile.MainInfo.TaskList.GetObjectId(),map);Card(reconcile.MainInfo.ReconcileFileList.GetObjectId(),graph);foreach(var file in reconcile.MainInfo.ReconcileFileList.Files)if(file.HardFileId!=Guid.Empty)FileRights(s.FileManager.GetFile(file.HardFileId),graph);else Versioned(file.FileId,graph);var path=c.GetObject<ApprovalPath>(reconcile.MainInfo.PathId);Card(path.GetObjectId(),map);foreach(var road in path.RoadMaps)Card(road.Stage.GetObjectId(),map);foreach(var record in path.StagesRecords)Card(record.Stage.GetObjectId(),map);foreach(var task in tasks){var taskMap=new Dictionary<string,CardDataRights>(map);foreach(string sid in taskMap.Keys.ToArray())if(taskMap[sid]!=Full)taskMap[sid]=Read;if(!taskService.IsTaskCompleted(task))foreach(var p in task.CurrentPerformers)Add(taskMap,p.Employee,Modify);Card(task.GetObjectId(),taskMap);}}
   }catch(Exception ex){failures.Add(new {card=raw.Id,error=ex.ToString()});}
   Runtime.Save(Path.Combine(dir,"last-run.json"),new {status=failures.Count==0?"applied":"partial",changed=changed,failures=failures,implementation="C#",utc=DateTime.UtcNow.ToString("o")});if(failures.Count>0)throw new InvalidOperationException("Access policy failed cards: "+failures.Count);
